# content_kids.py — 32호 KIDC 원고의 Methods·Results 문장(수치는 numbers_kids에서만, 2026-11-17).
#  인용 = [@key] 또는 [@web:...]; 번호식 [n]. 단독 저자 → 1인칭 금지. 영국식 철자. 결과 절 해석 금지.
#  제목 쌍점 금지, 시리즈 제목 틀 반복 금지. 보충 = Supplementary material(PDF).
from numbers_kids import load, ROB, RS, HTN, DM, BLR, DX, EDU, PA, PER
import os, pandas as pd
import rr_kids
N = load(); RR = rr_kids.load(); PL = RR['pool']; DS = RR['ds']; NA = RR['nat']; UM = RR['mc']; TL = RR['tilt']
def ci(v, src=None):
    r = (src or N["main"])[v]; return f"RR {r['IRR']:.3f}; 95% CrI {r['lo']:.3f}–{r['hi']:.3f}"
def tci(t): return f"RR {t[0]:.3f}; 95% CrI {t[1]:.3f}–{t[2]:.3f}"
M = N["main"]; T1 = N["T1"]; DF = N["defn"]; NT = DF["national"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["nco"][(o, v)]
S46 = lambda a, v: N["s46"][(a, v)]
SC = lambda s, v: N["sens_main"][s][v]
EN = {"전라남도": "South Jeolla", "경상북도": "North Gyeongsang", "경상남도": "South Gyeongsang", "충청남도": "South Chungcheong", "전라북도": "North Jeolla",
      "강원도": "Gangwon", "부산시": "Busan", "충청북도": "North Chungcheong", "대구시": "Daegu", "경기도": "Gyeonggi", "서울시": "Seoul", "인천시": "Incheon",
      "광주시": "Gwangju", "울산시": "Ulsan", "대전시": "Daejeon", "세종시": "Sejong", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
TITLE = "Reduced filtration or proteinuria? Unpacking a kidney screening judgement in Korea"
assert ":" not in TITLE and "229" not in TITLE and "standardi" not in TITLE.lower() and len(TITLE) <= 85 and "eGFR" not in TITLE
KEYWORDS = "Glomerular filtration rate; Proteinuria; Mass screening; Spatial analysis"
assert len(KEYWORDS.split(";")) <= 4
_LK = pd.read_csv(os.path.join(RS, "S1_likelihood.csv")); _LK = _LK[_LK.set == "REF_forced_only"].set_index("family").WAIC
_FAM = pd.read_csv(os.path.join(RS, "S3_main_fit.csv")).family.iloc[0]
assert _FAM == "nbinomial" and _LK["nbinomial"] < _LK["poisson"] and abs(_LK["nbinomial"] - N["waic_forced"]) < 0.05
NHYP = N["n_hyp"]; assert NHYP == 13
SUP = {"composition": "S1", "methods": "S2", "covariates": "S3", "checks": "S4", "specs": "S5", "windows": "S6", "stduncert": "S7", "strobe": "S8"}
def sup(k): return (f"Table {SUP[k]}" if k != "maps" else "Figure S1") + ", Supplementary material"
_pc = lambda v: f"{100*N['mv'][v]['cred_frac']:.0f}%"
ALT = N["retention"]
NULLV = ["screening_normalB_obesity_share", "current_smoking_rate"] + PA + ["diabetic_kidney_test_rate", "im_specialists_per_100k", "screening_uptake", BLR]
BEST = min(KH, key=lambda a: N["s43_waic"][a])
ALT_N = ALT[HTN]["n_specs"]
r1 = lambda x: f"{x:.1f}"; r2 = lambda x: f"{x:.2f}"
EX_P = lambda y: 100 * NT[y]["excess_share_of_dip"]
_UU = RR['U']; MCJMAX = float(_UU[_UU.scen.str.startswith('mc')].drop_duplicates('scen').hot_jaccard_vs_main.max())
_AS = RR['as']; _ym = _AS[_AS.year.between(2015, 2023) & (_AS.sex == 'M') & _AS.age.isin(['20-24', '25-29'])]; CBP = RR['cbp']
D18 = 100 * max(abs(1 - NA[y][k]) for y in range(2018, 2024) for k in ('denom_ratio_egfr', 'denom_ratio_dip'))
MXY = float(max(0.0, (100 * (_ym.j - _ym.hi_union)).max()))

METHODS = [
("Design and data",
 f"This ecological study used the general health screening programme of the National Health Insurance Service, which offers adults an examination every 2 years, including serum creatinine and a urine dipstick, and records a judgement for each examinee against criteria set in the health screening standards of the Ministry of Health and Welfare [@seong2017data; @web:mohw2026standard]. The outcome was the judgement of suspected kidney disease. In each edition of the standards examined (effective 2014, 2017, 2024 and 2026), the test-specific thresholds listed for this judgement were an estimated glomerular filtration rate (eGFR) below 60 mL/min/1.73 m², a serum creatinine above 1.5 mg/dL or dipstick proteinuria of 1+ or more; eGFR was calculated with the Modification of Diet in Renal Disease equation until 2023 and with the Chronic Kidney Disease Epidemiology Collaboration equation from 2024 [@web:mohw2026standard] ({sup('composition')}). The editions examined do not state how the test-specific thresholds are combined into the examinee-level judgement. Annual numbers of examinees with a judgement and of judgements by district, and nationally by sex and 5-year age group, were taken from the national statistics portal, with the national (by sex and age) and provincial distributions of eGFR and dipstick proteinuria and the national distribution of serum creatinine [@web:kosis2026screening]. Districts were harmonised to {N['n_districts']} units; one district created in 2012 without separate results was excluded ({sup('methods')})."),
("Composition of the judgement",
 "For each year from 2012, when eGFR distributions were first published, to 2024, the judged share in each sex and 5-year age group was compared with the shares with an eGFR below 60 mL/min/1.73 m² and with dipstick proteinuria of 1+ or more in the same group, each share taken over its own published denominator. If the tables covered the same examinees and every examinee meeting either criterion were judged, the judged share would lie between the larger component share and their sum, a reference rather than a test of individual judgements. With the non-IDMS-calibrated form of the Modification of Diet in Renal Disease equation (coefficient 186), a creatinine above 1.5 mg/dL with an eGFR of 60 mL/min/1.73 m² or more is arithmetically possible only in men aged 20–26 years with a creatinine above 1.5 and up to 1.57 mg/dL, and with the IDMS-calibrated form (coefficient 175) not at all in adults, so the creatinine criterion was examined by comparing young men with young women and by testing whether judged shares could be produced by a creatinine of 1.5 mg/dL or more with proteinuria instead of a low eGFR. National shares were also directly standardised to the 2019 examinees, and provincial judged shares were regressed on both component shares with year effects. The analysis used 2015–2023, which ends before the change of equation in 2024 and excludes the first years of eGFR reporting (2012–2014), when the judged share was below the low-eGFR share; composition within the period was not assumed to be constant."),
("Age and sex standardisation",
 "Expected numbers were obtained by indirect standardisation, applying national rates by sex and 5-year age group to the estimated examinees of each district and rescaling each year to the national total. The sex and age structure of district examinees, which is not published, was estimated from the resident population and national uptake and scaled to the observed district examinees by sex; expected numbers computed from the resident population were used as a sensitivity analysis. Because the examinee structure was estimated rather than observed, a bias analysis refitted the principal model with expected numbers recomputed after tilting the estimated examinee age structure of each district: 20 random replicates and 8 scenarios in which the tilt was tied to the treated hypertension and diabetes share or the urban share (±0.3 and ±0.6 log units per 35 years of age per SD; Table S2, Supplementary material)."),
("Covariates",
 f"Thirteen district characteristics and their expected directions were fixed before any covariate model was fitted ({sup('covariates')}; checks in {sup('checks')}). Upstream characteristics were the summed shares of examinees treated for hypertension and for diabetes, the shares with suspected hypertension and suspected diabetes at screening, and the obesity lifestyle-management share. Behaviour comprised current smoking, walking and moderate or vigorous physical activity (Community Health Survey) and public sports facilities; care and selection, urine albumin testing in diabetes, internal medicine specialists and screening uptake; and structure, basic livelihood security and tertiary education. Urban population share, physician density, sex ratio, fiscal autonomy and the share aged 80 years or older were forced into every model. Covariates were standardised to 1 standard deviation (SD)."),
("Statistical analysis",
 f"The likelihood was chosen by the widely applicable information criterion (WAIC). Models had an offset of log expected numbers, a Besag–York–Mollié 2 district effect with penalised-complexity priors [@riebler2016intuitive] and random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate]. Rate ratios (RRs) per 1 SD are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. RRs are mutually adjusted ecological associations, not causal effects; intervals were not adjusted for multiplicity. In {N['n_specs_total']} random covariate subsets, a covariate was subset-stable if credible in at least 75% of the subsets containing it, with the same sign in at least 95%. Residual hot and cold spots had a posterior probability of a residual spatial RR above 1 greater than 0.95 or less than 0.05."),
("Sensitivity analyses",
 f"Knorr-Held type I–IV space–time interactions were added [@knorrheld2000bayesian]; subset-stable covariates were split into district means and within-district deviations; the model was refitted in 2015–2018 and 2019–2023; expected numbers were recomputed from the resident population; and the provincial shares with an eGFR below 60 mL/min/1.73 m² and with dipstick proteinuria were added to test whether the associations reflected one component. Further specifications varied the likelihood, time effects, priors, neighbourhoods, lags and left-out provinces or years. Treated gastric cancer and infectious disease served as comparison outcomes, hit-and-run accidents, fires and recycling as negative-control exposures, and E-values quantified the confounding needed to explain associations ({sup('specs')}). The study is reported according to the STROBE statement [@vonelm2007strengthening]. The author used Claude (Anthropic) and ChatGPT (OpenAI) only for translation and English-language editing of the manuscript."),
]

C1 = lambda a, v: N["comp"][(a, v)]
RESULTS = [
("What the judgement counts",
 f"Among examinees aged 20–39 years in 2015–2023, {PL.loc[('F','20-39'),'a']:.2f}% of women and {PL.loc[('M','20-39'),'a']:.2f}% of men had an eGFR below 60 mL/min/1.73 m², and the judged shares were {PL.loc[('F','20-39'),'j_b']:.2f} (women) and {PL.loc[('M','20-39'),'j_b']:.2f} (men) times the shares with dipstick proteinuria of 1+ or more, with little change between years (women {RR['y2039']['F'].min():.2f}–{RR['y2039']['F'].max():.2f}; men {RR['y2039']['M'].min():.2f}–{RR['y2039']['M'].max():.2f}). At ages 40 years or older the judged shares exceeded the sum of the shares with a creatinine of 1.5 mg/dL or more and with proteinuria (women aged 70 or older, {CBP.loc[('F','70+'),'j']:.1f}% vs at most {CBP.loc[('F','70+'),'c_hi']+CBP.loc[('F','70+'),'b']:.1f}%). Among examinees aged 70 years or older, the judged shares were {PL.loc[('F','70+'),'j_a']:.2f} (women) and {PL.loc[('M','70+'),'j_a']:.2f} (men) times the shares with an eGFR below 60 mL/min/1.73 m² (2015, {RR['o70'].loc[2015,'F']:.2f} and {RR['o70'].loc[2015,'M']:.2f}; 2023, {RR['o70'].loc[2023,'F']:.2f} and {RR['o70'].loc[2023,'M']:.2f}) ({sup('composition')}). Standardised to the 2019 examinees, the share with an eGFR below 60 mL/min/1.73 m² fell from {100*DS[2015]['a_std']:.2f}% to {100*DS[2023]['a_std']:.2f}% between 2015 and 2023, the share with dipstick proteinuria of 1+ or more rose from {100*DS[2015]['b_std']:.2f}% to {100*DS[2023]['b_std']:.2f}%, trace results, which are not a criterion, rose from {100*DS[2015]['trace_std']:.2f}% to {100*DS[2023]['trace_std']:.2f}%, and the judged share rose from {100*DS[2015]['j_std']:.2f}% to {100*DS[2023]['j_std']:.2f}%. Crude, the judged share was {NA[2023]['j']/NA[2023]['a']:.2f} times the low-eGFR share in 2023 and {min(NA[y]['j']/NA[y]['a'] for y in (2012,2013,2014)):.2f}–{max(NA[y]['j']/NA[y]['a'] for y in (2012,2013,2014)):.2f} times it in 2012–2014 (Fig. 1B). The eGFR and dipstick distributions covered {100*(min(NA[y]['denom_ratio_egfr'] for y in (2015,2016,2017))-1):.1f}–{100*(max(NA[y]['denom_ratio_dip'] for y in (2015,2016,2017))-1):.1f}% more examinees than the judgement tables in 2015–2017, mostly at ages 40–44 and 65–69 years, and within {D18:.1f}% of them from 2018; bounds are approximate in 2015–2017. Across {DF['n_province']} provinces, the two component shares explained {100*DF['r2_between_both_2015_2023']:.0f}% of between-province differences in the judged share."),
("Screening and geography",
 f"In 2015–2023, {N['exam_total']/1e6:.1f} million examinations recorded {N['cases_total']:,} judgements in {N['n_rows']:,} district-years (Table 1). Pooled standardised ratios were {T1[PER]['sir_p10']:.2f} and {T1[PER]['sir_p90']:.2f} at the 10th and 90th percentile districts. Moran's I of observed log ratios was {N['moran_pooled']:.2f} pooled ({N['moran_year_min']:.2f}–{N['moran_year_max']:.2f} annually). Residual RRs ranged from {N['rr_min']:.2f} to {N['rr_max']:.2f}, with {N['n_hot']} hot spots, {N['hot_capital']} of them in the capital region of Seoul, Incheon and Gyeonggi, and {N['n_cold']} cold spots, mainly in {sidos(N['cold_by_sido'], 3)} (Fig. 1A); annual rankings were moderately concordant (Kendall's W {N['kendall_W']:.2f}) ({sup('maps')})."),
("District correlates",
 f"The negative binomial likelihood was selected (WAIC {_LK['nbinomial']:,.1f} vs {_LK['poisson']:,.1f} for Poisson), and adding the {NHYP} covariates lowered WAIC to {N['waic_main']:,.1f}. Four of the {NHYP} hypothesis covariates were credible and three were subset-stable (Table 2). The standardised ratio was higher with a larger summed share of examinees treated for hypertension and for diabetes ({ci(DX)}), more suspected hypertension at screening ({ci(HTN)}) and more suspected diabetes at screening ({ci(DM)}); each was credible in every subset that contained it. Against the expected direction, tertiary education was associated with a higher ratio ({ci(EDU)}) but was credible in only {_pc(EDU)} of subsets. Walking ({ci('walking_practice_rate')}), moderate or vigorous activity ({ci('moderate_pa_rate')}), public sports facilities ({ci('public_sports_facilities_per_100k')}), smoking, obesity, albumin testing, specialists, uptake and basic livelihood security ({ci(BLR)}) were not credibly associated, nor were the negative-control exposures."),
("Robustness",
 f"All four space–time interaction types fitted better than the principal model (type {BEST.replace('KH_type', '')} best), and the three subset-stable covariates remained credible in each (Fig. 2; Table 2). With the provincial eGFR and proteinuria shares added (both credible; WAIC lower by {N['waic_main'] - N['comp_waic']['K1_prov_components']:,.0f}), the estimates were {tci(C1('K1_prov_components', DX))} for the treated share, {tci(C1('K1_prov_components', HTN))} for suspected hypertension and {tci(C1('K1_prov_components', DM))} for suspected diabetes. Within-district and between-district components are given in {sup('specs')}. The three covariates were credible in both windows and with expected numbers from the resident population ({sup('windows')}), and in {ALT[DX]['kept']}, {ALT[HTN]['kept']} and {ALT[DM]['kept']} of {ALT_N} alternative specifications. With comparison outcomes the three had rate ratios of 1.000 or below. Across the {RR['n_mc']} random replicates of the examinee structure, the treated share (RR {UM[DX]['lo']:.3f}–{UM[DX]['hi']:.3f}) and suspected diabetes (RR {UM[DM]['lo']:.3f}–{UM[DM]['hi']:.3f}) were credible in all {RR['n_mc']} and suspected hypertension (RR {UM[HTN]['lo']:.3f}–{UM[HTN]['hi']:.3f}) in {UM[HTN]['ncred']}; the residual hot spots matched those of the principal model with a Jaccard index of {RR['mc_hotJ'][0]:.2f}–{MCJMAX:.2f}. With the examinee age gradient tied to the urban share, all three remained credible; tied to the treated share, the treated-share estimate was {tci(TL[('tilt_dx_p03', DX)])} at +0.3 and {tci(TL[('tilt_dx_p06', DX)])} at +0.6 log units, at which the interval for suspected hypertension also included 1 ({tci(TL[('tilt_dx_p06', HTN)])}), and {tci(TL[('tilt_dx_m06', DX)])} at −0.6 log units. In a district 1 SD above the mean treated share, +0.6 log units changes the relative numbers of examinees aged 80–84 and 20–24 years 2.8-fold ({sup('stduncert')}). E-values were small (point estimates {N['evalue'][DX]['E_point']:.2f}, {N['evalue'][HTN]['E_point']:.2f} and {N['evalue'][DM]['E_point']:.2f})."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
assert set(N["robust_set"]) == set(ROB) and all(N["mv"][v]["cred_frac"] == 1 for v in ROB)
assert N["n_cred_hyp"] == 4 and all(M[v]["cred"] and M[v]["IRR"] > 1 for v in ROB + [EDU]) and not N["mv"][EDU]["robust"]
assert not any(M[v]["cred"] for v in NULLV) and not any(N["negctl"][v]["cred"] for v in N["negctl"])
assert all(N["s43_waic"][a] < N["waic_main"] for a in KH) and all(S43(a, v)[3] for a in KH for v in ROB)
assert all(N["comp"][("K1_prov_components", v)][3] for v in ROB + ["prov_egfr_z", "prov_dip_z"]) and N["comp_waic"]["K1_prov_components"] < N["waic_main"]
assert all(N["win_irr"][(v, w)][3] for v in ROB for w in ("W1_2015-18", "W2_2019-23")) and all(N["epop"][v][3] for v in ROB)
assert N["bw"][DX + "__within"][3] and N["bw"][HTN + "__within"][3] and N["bw"][DM + "__between"][3] and not N["bw"][DX + "__between"][3]
assert all(N["nco"][(o, v)][0] <= 1.0 for o in ("GCA", "INFECT") for v in ROB)
assert N["covid"][HTN][3] and N["covid"][HTN][0] < 1 and N["covid"][DM][3] and N["covid"][DM][0] < 1
assert NT[2012]["ratio_susp_to_egfr"] < 1 and NT[2014]["ratio_susp_to_egfr"] < 1 and all(NT[y]["ratio_susp_to_egfr"] >= 1 for y in range(2015, 2024))
assert round(100 * (NT[2023]["ratio_susp_to_egfr"] - 1)) == 68 and round(100 * DF["r2_between_both_2015_2023"]) == 76 and round(N["exam_total"] / 1e6, 1) == 137.5
assert (round(M[DX]["IRR"], 3), M[DX]["lo"], M[DX]["hi"]) == (1.084, 1.055, 1.114) and (M[HTN]["IRR"], M[HTN]["lo"], M[HTN]["hi"]) == (1.013, 1.003, 1.024) and (M[DM]["IRR"], M[DM]["lo"], M[DM]["hi"]) == (1.018, 1.007, 1.028)
assert list(N["cold_by_sido"])[:2] == ["경상북도", "경상남도"] and N["hot_capital"] >= N["n_hot"] / 2

if __name__ == "__main__":
    import re
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
